#!/bin/sh
set -u; livespec_pr_arm() { gh pr merge --${LIVESPEC_STAGE_INPUT_MERGE_MODE} --auto --delete-branch --match-head-commit "$1" "$2" 2>&1; }; branch="${LIVESPEC_PUBLISH_BRANCH:-}"; if test -z "$branch"; then echo 'LIVESPEC_PR_NO_BRANCH: no LIVESPEC_PUBLISH_BRANCH in this script environment, so the pull request to ready cannot be named; failing closed' >&2; exit 1; fi; state=$(git rev-parse --git-path livespec-publication); mkdir -p "$state"; visits=$(cat "$state/livespec-pr-visit-count" 2>/dev/null || echo 0); if ! test "$visits" -ge 0 2>/dev/null; then echo "LIVESPEC_PR_VISIT_COUNT_UNREADABLE: the recorded pr visit count $visits is not a number, so a refresh-route marker could not be named for this visit and pr_route could not tell this visit from an earlier one; failing closed rather than recording a marker nothing can attribute" >&2; exit 1; fi; visit=$((visits + 1)); printf '%s\n' "$visit" > "$state/livespec-pr-visit-count"; pushed=$(cat "$state/livespec-publish-head" 2>/dev/null || true); if test -z "$pushed"; then pushed="${LIVESPEC_RESUME_PUBLISHED_HEAD:-}"; fi; if test -z "$pushed"; then echo 'LIVESPEC_PR_NO_PROVENANCE: this run records no published head, so what it pushed cannot be compared with what its proof names; failing closed' >&2; exit 1; fi; number=$(gh pr list --head "$branch" --state open --json number --jq 'map(.number)|first'); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: the forge could not be asked which pull request is open for $branch; failing closed rather than guessing" >&2; exit 1; fi; if test -z "$number" || test "$number" = "null"; then number=$(gh pr list --head "$branch" --state all --json number --jq 'map(.number)|max'); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: the forge could not be asked which pull requests exist for $branch; failing closed rather than guessing" >&2; exit 1; fi; fi; if test -z "$number" || test "$number" = "null"; then echo "LIVESPEC_PR_ABSENT: the forge reports no pull request for $branch, yet publish_draft is the only route into this stage and it opens one; failing closed rather than creating a second" >&2; exit 1; fi; state_name=$(gh pr view "$number" --json state --jq .state); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: pull request #$number state could not be read; failing closed" >&2; exit 1; fi; head=$(gh pr view "$number" --json headRefOid --jq .headRefOid); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: pull request #$number head could not be read, so no identity check is possible; failing closed" >&2; exit 1; fi; if test "$state_name" = "MERGED"; then merged=$(gh pr view "$number" --json mergeCommit --jq '.mergeCommit.oid'); echo "PR_NUMBER=$number"; echo "MERGE_LANDED=$merged"; echo "LIVESPEC_PR_ALREADY_MERGED: pull request #$number merged as $merged before this stage ran, which is the outcome it was publishing for; nothing is left to ready or arm" >&2; exit 0; fi; if test "$state_name" != "OPEN"; then echo "LIVESPEC_PR_CLOSED_UNMERGED: pull request #$number for $branch is $state_name rather than OPEN or MERGED, so the publication a human closed must not be reopened by a script; failing closed" >&2; exit 1; fi; program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-publication-head.py"; if test ! -f "$program"; then echo "LIVESPEC_PR_PROOF_PROGRAM_ABSENT: the Dispatcher-materialized publication-head program is not at $program, so the head whose proof was captured and verified cannot be established; it is the ONE reader of the record format and this stage must not guess at it. Failing closed" >&2; exit 1; fi; proof=$(python3 "$program" --pull-request "$number" --require captured --require verified); if test $? -ne 0; then echo "LIVESPEC_PR_PROOF_IDENTITY_UNESTABLISHED: the publication-head program could not establish the head whose proof was captured AND verified on pull request #$number; its own cause is above. Failing closed rather than readying a pull request on an unchecked proof identity" >&2; exit 1; fi; if test "$proof" != "$head"; then proof_tree=$(git rev-parse --verify --quiet "$proof^{tree}" 2>/dev/null); head_tree=$(git rev-parse --verify --quiet "$head^{tree}" 2>/dev/null); if test -n "$proof_tree" && test "$proof_tree" = "$head_tree" && git merge-base --is-ancestor "$head" "$proof" 2>/dev/null; then echo "LIVESPEC_PR_PROOF_ON_UNCHANGED_CHECKPOINT: the latest captured and verified Proof of Done records on pull request #$number name $proof, an unpushed descendant of the pull request head $head with the identical tree $head_tree (an engine checkpoint commit), so that proof is of the tree this pull request carries" >&2; else echo "LIVESPEC_PR_PROOF_HEAD_MISMATCH: the latest captured and verified Proof of Done records on pull request #$number name head $proof while the pull request is at $head, so that proof is of a tree this pull request no longer carries; failing closed rather than reusing it" >&2; exit 1; fi; fi; if test "$head" != "$pushed"; then echo "LIVESPEC_PR_UNEXPECTED_HEAD: pull request #$number is at $head while this run published $pushed, so the pull request carries a head this run did not push; failing closed" >&2; exit 1; fi; title="${LIVESPEC_PR_TITLE:-}"; if test -z "$title"; then echo "LIVESPEC_PR_TITLE_ABSENT: no Dispatcher-rendered title reached this stage, so pull request #$number keeps the publish branch name $branch as its title; the overlay projection that renders it is broken, and publication continues because a title decides nothing about the tree" >&2; title="$branch"; fi; body_file="${LIVESPEC_PR_BODY_FILE:-${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-pr-body.md}"; if test -s "$body_file"; then gh pr edit "$number" --title "$title" --body-file "$body_file"; else echo "LIVESPEC_PR_BODY_ABSENT: no Dispatcher-rendered body at $body_file, so pull request #$number keeps the publish_draft placeholder body; the prepare step that materializes it is broken, and publication continues because a body decides nothing about the tree" >&2; gh pr edit "$number" --title "$title"; fi; if test $? -ne 0; then echo "LIVESPEC_PR_EDIT_FAILED: the rendered title and body could not be applied to pull request #$number; failing closed before readying it" >&2; exit 1; fi; draft=$(gh pr view "$number" --json isDraft --jq .isDraft); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: pull request #$number draft state could not be read, so readying it cannot be made idempotent; failing closed" >&2; exit 1; fi; if test "$draft" = "true"; then if ! gh pr ready "$number"; then echo "LIVESPEC_PR_READY_FAILED: pull request #$number is a draft and could not be marked ready for review; failing closed" >&2; exit 1; fi; else echo "LIVESPEC_PR_ALREADY_READY: pull request #$number is already out of draft, so nothing was readied" >&2; fi; if test "${LIVESPEC_STAGE_INPUT_MERGE_HOLD}" = "true"; then arming=$(gh pr view "$number" --json autoMergeRequest --jq '.autoMergeRequest'); if test $? -ne 0; then echo "LIVESPEC_PR_LOOKUP_FAILED: pull request #$number auto-merge state could not be read, so the hold cannot be proven unarmed; failing closed" >&2; exit 1; fi; if test -n "$arming" && test "$arming" != "null"; then echo "LIVESPEC_PR_HOLD_ARMED: pull request #$number carries an auto-merge request while this item merge hold stands; a script must not disarm it, so failing closed for a human" >&2; exit 1; fi; echo "PR_NUMBER=$number"; echo "MERGE_HOLD=held"; echo "LIVESPEC_PR_HELD: pull request #$number is ready and deliberately unarmed under this item merge hold; an operator releases it with the set-merge-hold valve" >&2; exit 0; fi; if ! rejection=$(livespec_pr_arm "$head" "$number"); then landed=$(gh pr view "$number" --json state --jq .state) || landed="(unobservable)"; if test "$landed" = "MERGED"; then merged=$(gh pr view "$number" --json mergeCommit --jq '.mergeCommit.oid'); echo "PR_NUMBER=$number"; echo "MERGE_LANDED=$merged"; echo "LIVESPEC_PR_MERGED_WHILE_ARMING: pull request #$number merged as $merged before the arming command landed, which is the outcome it was arming for" >&2; exit 0; fi; rejection=$(printf '%s' "$rejection" | tr '\n' ' '); current=$(gh pr view "$number" --json headRefOid --jq .headRefOid) || current=""; if test -z "$current"; then current="(unobservable)"; fi; mergeability=$(gh pr view "$number" --json mergeStateStatus --jq .mergeStateStatus) || mergeability=""; if test -z "$mergeability"; then mergeability="(unobservable)"; fi; if git fetch --no-tags origin "refs/heads/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}:refs/remotes/origin/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}"; then base=$(git rev-parse "refs/remotes/origin/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}" 2>/dev/null || true); else base=""; fi; if test -z "$base"; then base="(unobservable)"; fi; if test "$current" = "(unobservable)"; then head_match="(not measured)"; elif test "$current" = "$head"; then head_match="equal"; else head_match="differs"; fi; base_ancestor="(not measured)"; if test "$head_match" = "equal" && test "$base" != "(unobservable)"; then if git merge-base --is-ancestor "$base" "$current"; then base_ancestor="yes"; else base_ancestor="no"; fi; fi; echo "LIVESPEC_PR_ARM_REJECTED: forge rejection: $rejection | pull request state: $landed | mergeability: $mergeability | pull request head: $current | head equals the verified head: $head_match | default branch tip: $base | default branch tip is an ancestor of the head: $base_ancestor" >&2; if test "$head_match" = "differs"; then echo "LIVESPEC_PR_UNEXPECTED_HEAD: pull request #$number is at $current while this run proved and pushed $head, so the pull request carries a head this run did not push; failing closed" >&2; exit 1; fi; if test "$head_match" = "(not measured)"; then echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number and it is $landed rather than MERGED, and the forge could not report the head it now carries, so whether the default branch advanced past the proof-verified head cannot be established; failing closed rather than routing to pr_refresh on an unobservable answer" >&2; exit 1; fi; if test "$mergeability" = "(unobservable)"; then echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number and the forge could not report its mergeability, so the rejection cannot be attributed; failing closed rather than routing to pr_refresh on an unobservable answer" >&2; exit 1; fi; if test "$base" = "(unobservable)"; then echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number and the authoritative default branch ${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH} could not be fetched from origin, so whether it advanced past the proof-verified head cannot be established; failing closed rather than routing to pr_refresh on an unobservable answer" >&2; exit 1; fi; if test "$base_ancestor" != "no"; then echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number and it is $landed rather than MERGED while the default branch tip $base is already an ancestor of the proof-verified head $head, so the default branch has not advanced past this head and the forge cause named above is the fault; failing closed" >&2; exit 1; fi; if test -f "$state/livespec-pr-refresh-clean"; then if test "$mergeability" = "DIRTY"; then printf '%s:conflict\n' "$visit" > "$state/livespec-pr-refresh-route"; echo "LIVESPEC_PR_REFRESH_ROUTE: the forge reports pull request #$number in conflict with the default branch (tip $base) after this run refreshed cleanly once, so pr visit $visit recorded the refresh-route marker and pr_route will re-enter pr_refresh, which counts that refresh once toward the three-refresh bound" >&2; exit 0; fi; arm_attempts=5; arm_wait="${LIVESPEC_PR_ARM_RETRY_SECONDS:-20}"; if ! test "$arm_wait" -ge 0 2>/dev/null; then arm_wait=20; fi; attempt=0; while test "$attempt" -lt "$arm_attempts"; do attempt=$((attempt + 1)); sleep "$arm_wait"; mergeability=$(gh pr view "$number" --json mergeStateStatus --jq .mergeStateStatus) || mergeability=""; if test -z "$mergeability"; then echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number and the forge could not report its mergeability before arming attempt $attempt, so the rejection cannot be attributed; last forge rejection: $rejection; failing closed rather than routing to pr_refresh on an unobservable answer" >&2; exit 1; fi; if test "$mergeability" = "DIRTY"; then printf '%s:conflict\n' "$visit" > "$state/livespec-pr-refresh-route"; echo "LIVESPEC_PR_REFRESH_ROUTE: the forge now reports pull request #$number in conflict with the default branch before arming attempt $attempt, so pr visit $visit recorded the refresh-route marker and pr_route will re-enter pr_refresh, which counts that refresh once toward the three-refresh bound" >&2; exit 0; fi; if retry_rejection=$(livespec_pr_arm "$head" "$number"); then echo "PR_NUMBER=$number"; echo "LIVESPEC_PR_READY_AND_ARMED: pull request #$number carrying the proof-verified head $head is ready with auto-merge armed on retry $attempt after the run's one clean refresh" >&2; exit 0; fi; landed=$(gh pr view "$number" --json state --jq .state) || landed="(unobservable)"; if test "$landed" = "MERGED"; then merged=$(gh pr view "$number" --json mergeCommit --jq '.mergeCommit.oid'); echo "PR_NUMBER=$number"; echo "MERGE_LANDED=$merged"; echo "LIVESPEC_PR_MERGED_WHILE_ARMING: pull request #$number merged as $merged before the arming retry landed, which is the outcome it was arming for" >&2; exit 0; fi; rejection=$(printf '%s' "$retry_rejection" | tr '\n' ' '); current=$(gh pr view "$number" --json headRefOid --jq .headRefOid) || current=""; if test -z "$current"; then current="(unobservable)"; fi; if test "$current" = "(unobservable)"; then head_match="(not measured)"; elif test "$current" = "$head"; then head_match="equal"; else head_match="differs"; fi; if git fetch --no-tags origin "refs/heads/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}:refs/remotes/origin/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}"; then base=$(git rev-parse "refs/remotes/origin/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}" 2>/dev/null || true); else base=""; fi; if test -z "$base"; then base="(unobservable)"; fi; base_ancestor="(not measured)"; if test "$head_match" = "equal" && test "$base" != "(unobservable)"; then if git merge-base --is-ancestor "$base" "$current"; then base_ancestor="yes"; else base_ancestor="no"; fi; fi; echo "LIVESPEC_PR_ARM_REJECTED: forge rejection: $rejection | pull request state: $landed | mergeability: $mergeability | pull request head: $current | head equals the verified head: $head_match | default branch tip: $base | default branch tip is an ancestor of the head: $base_ancestor | arming retry: $attempt of $arm_attempts" >&2; if test "$head_match" = "differs"; then echo "LIVESPEC_PR_UNEXPECTED_HEAD: pull request #$number is at $current while this run proved and pushed $head, so the pull request carries a head this run did not push; failing closed" >&2; exit 1; fi; done; echo "LIVESPEC_PR_ARM_FAILED: auto-merge could not be armed on pull request #$number after $arm_attempts retries following this run's one clean refresh, and the forge does not report the pull request in conflict, so default-branch movement is left to the merge path and this stage cannot arm it; last forge rejection: $rejection | pull request state: $landed | mergeability: $mergeability; failing closed" >&2; exit 1; fi; printf '%s\n' "$visit" > "$state/livespec-pr-refresh-route"; echo "LIVESPEC_PR_REFRESH_ROUTE: the default branch advanced to $base after this run refreshed onto its predecessor and before this arming, so the forge rejected an arming bound to the still-proof-verified head $head; pr visit $visit recorded the refresh-route marker and pr_route will re-enter pr_refresh, which refreshes onto the advanced default branch" >&2; exit 0; fi; echo "PR_NUMBER=$number"; echo "LIVESPEC_PR_READY_AND_ARMED: pull request #$number carrying the proof-verified head $head is ready with auto-merge armed" >&2; exit 0
